export function validate() {
  const problems = [];
  const seen = new Set();
  for (const s of SLIDES) {
    if (seen.has(s.slug)) problems.push(`duplicate slide slug: ${s.slug}`);
    seen.add(s.slug);
    if (!Number.isInteger(s.page) || s.page < 1 || s.page > 26) problems.push(`${s.slug}: page ${s.page} is not in the 26-page PDF`);
    /* Alt text is the slide for anyone who cannot see it. A short one is a slide
       thrown away, so the floor is deliberately high. */
    if (!s.alt || s.alt.length < 80) problems.push(`${s.slug}: alt text is too thin to stand in for the slide`);
  }
  return problems;
}
